# Surah Al-An'am (chapter 6) — part 13: ayat 124-133 (IDs 913-922)
SURAH = 6

ENTRIES = {
913: (
"اور جب — ان — کے — پاس — کوئی آیت آئے تو وہ کہتے — ہم — ہرگز — ایمان نہیں لائیں گے جب تک — ہمیں — ویسا — ہی — دیا جائے جیسا — اللہ کے — رسولوں — کو دیا گیا ہے — اللہ بہتر جانتا ہے کہ اپنی — رسالت — کہاں رکھے — مجرموں کو — عنقریب — اللہ — کے — یہاں — ذلت — اور — سخت — عذاب — پہنچے گا — اس وجہ سے جو وہ — چال — چلتے تھے",
"""۱۔ کفار — نبوت — کی شرط — مانتے ہیں۔
۲۔ ’’وَإِذَا جَاءَتْهُمْ آيَۃٌ قَالُوا لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَا أُوتِيَ رُسُلُ اللّٰہِ‘‘ — اور جب — ان — کے — پاس — کوئی آیت آئے تو وہ کہتے — ہم — ہرگز — ایمان نہیں لائیں گے جب تک — ہمیں — ویسا — ہی — دیا جائے جیسا — اللہ کے — رسولوں — کو دیا گیا ہے — یعنی کفار — عیسیٰؑ اور موسیٰؑ کی طرح — براہِ راست وحی — مانگتے تھے۔
۳۔ ’’اللّٰہُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُ‘‘ — اللہ بہتر جانتا ہے کہ اپنی — رسالت — کہاں رکھے — یعنی نبوت — اللہ کا چناؤ ہے — کسی کی شرط نہیں۔
۴۔ ’’سَيُصِيبُ الَّذِينَ أَجْرَمُوا صَغَارٌ عِندَ اللّٰہِ وَعَذَابٌ شَدِيدٌ بِمَا كَانُوا يَمْكُرُونَ‘‘ — مجرموں کو — عنقریب — اللہ — کے — یہاں — ذلت — اور — سخت — عذاب — پہنچے گا — اس وجہ سے جو وہ — چال — چلتے تھے — یعنی — کفار — کی — چال — ان — کو — ذلت — عذاب — میں مبتلا کرے گی۔
۵۔ عملی سبق: نبوت — اللہ کا چناؤ ہے؛ شرطیں — مت لگاؤ؛ کبر و حسد — سے بچو۔"""
),
914: (
"پس — جسے — اللہ — ہدایت — دینا چاہے — اس — کا سینہ — اسلام کے لیے — کھول دیتا ہے — اور جسے — گمراہ — کرنا چاہے — اس — کا سینہ — تنگ — تنگ — کر دیتا ہے —گویا وہ آسمان میں — چڑھ — رہا — ہے — اسی طرح اللہ — کفر کرنے والوں پر — رجس (ناپاکی) — ڈالتا — ہے",
"""۱۔ ہدایت والے کا سینہ — اسلام کے لیے — کھلا۔
۲۔ ’’فَمَن يُرِدِ اللّٰہُ أَن يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلَامِ‘‘ — پس — جسے — اللہ — ہدایت — دینا چاہے — اس — کا سینہ — اسلام کے لیے — کھول دیتا ہے — یعنی ہدایت والے کا سینہ — اسلام کے لیے — پھیلتا ہے۔
۳۔ ’’وَمَن يُرِدْ أَن يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِي السَّمَاءِ‘‘ — اور جسے — گمراہ — کرنا چاہے — اس — کا سینہ — تنگ — تنگ — کر دیتا ہے — گویا وہ آسمان میں — چڑھ — رہا — ہے — یعنی گمراہ — کے لیے اسلام — سانس لینے کے برابر — مشکل ہو جاتا ہے۔
۴۔ ’’كَذَٰلِكَ يَجْعَلُ اللّٰہُ الرِّجْسَ عَلَى الَّذِينَ لَا يُؤْمِنُونَ‘‘ — اسی طرح اللہ — کفر کرنے والوں پر — رجس (ناپاکی) — ڈالتا — ہے — یعنی کفر — رجس — عذاب میں — مبتلا کرتا ہے۔
۵۔ عملی سبق: اسلام — کو دل کھول کر قبول کرو؛ کفر سے بچو؛ اللہ سے ہدایت مانگو۔"""
),
915: (
"اور یہی تمہارے رب کی — سیدھی — راہ ہے — ہم نے — ان لوگوں کے لیے جو نصیحت سنتے ہیں — آیات — تفصیل سے بیان کی ہیں",
"""۱۔ اسلام کی راہ — سیدھی — ہے۔
۲۔ ’’وَهَٰذَا صِرَاطُ رَبِّكَ مُسْتَقِيمًا قَدْ فَصَّلْنَا الْآيَاتِ لِقَوْمٍ يَذَّكَّرُونَ‘‘ — اور یہی تمہارے رب کی — سیدھی — راہ ہے — ہم نے — ان لوگوں کے لیے جو نصیحت سنتے ہیں — آیات — تفصیل سے بیان کی ہیں — یعنی اللہ نے آیات — تفصیل سے — بیان کی ہیں تاکہ نصیحت سنیں۔
۳۔ عملی سبق: اللہ کی — سیدھی — راہ اختیار کرو؛ نصیحت سنو۔"""
),
916: (
"ان کے لیے — ان کے رب کے پاس — دار السلام (امن کا گھر) ہے — اور وہ — ان — کارساز ہے — ان — کے اعمال کے مطابق",
"""۱۔ امن کا گھر — حکمرانی — اللہ کی طرف سے۔
۲۔ ’’لَهُمْ دَارُ السَّلَامِ عِندَ رَبِّهِمْ وَهُوَ وَلِيُّهُم بِمَا كَانُوا يَعْمَلُونَ‘‘ — ان کے لیے — ان کے رب کے پاس — دار السلام (امن کا گھر) ہے — اور وہ — ان — کارساز ہے — ان — کے اعمال کے مطابق — یعنی اہل ایمان — کے لیے — اللہ کا — امن کا گھر — ہے۔
۳۔ عملی سبق: اللہ کے امن کے گھر (جنت) — کی — تلاش — کرو؛ نیک اعمال کرو۔"""
),
917: (
"اور — جس دن — وہ — سب — کو — جمع کرے گا — اے جن کی جماعت — تم — نے — انسانوں میں سے — بہت — بڑھا لیا — اور ان کے انسان دوست کہیں گے — اے ہمارے رب — ہم — میں سے ایک — دوسرے سے — فائدہ — اٹھاتے رہے — اور اب ہم — اپنی — مقررہ مدت — تک — پہنچ گئے — جو تونے ہمارے لیے مقرر کی — (اللہ) کہے گا: آگ — تمہارے ٹھکانے ہے — تم — اس — میں — ہمیشہ رہو گے — سوائے جو اللہ چاہے — بے شک تمہارا رب — حکمت والا — جاننے والا ہے",
"""۱۔ جن و انس — قیامت میں — جمع ہوں گے۔
۲۔ ’’وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَا مَعْشَرَ الْجِنِّ قَدِ اسْتَكْثَرْتُم مِّنَ الْإِنسِ‘‘ — اور — جس دن — وہ — سب — کو — جمع کرے گا — اے جن کی جماعت — تم — نے — انسانوں میں سے — بہت — بڑھا لیا — یعنی جنوں نے — انسانوں کو بہکایا — تھا۔
۳۔ ’’وَقَالَ أَوْلِيَاؤُهُم مِّنَ الْإِنسِ رَبَّنَا اسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَا أَجَلَنَا الَّذِي أَجَّلْتَ لَنَا‘‘ — اور ان کے انسان دوست کہیں گے — اے ہمارے رب — ہم — میں سے ایک — دوسرے سے — فائدہ — اٹھاتے رہے — اور اب ہم — اپنی — مقررہ مدت — تک — پہنچ گئے — جو تونے ہمارے لیے مقرر کی — یعنی انسان اور جن — ایک دوسرے سے — فائدہ اٹھاتے رہے — ایسی دوستی — ختم ہو گئی۔
۴۔ ’’قَالَ النَّارُ مَثْوَاكُمْ خَالِدِينَ فِيهَا إِلَّا مَا شَاءَ اللّٰہُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ‘‘ — (اللہ) کہے گا: آگ — تمہارے ٹھکانے ہے — تم — اس — میں — ہمیشہ رہو گے — سوائے جو اللہ چاہے — بے شک تمہارا رب — حکمت والا — جاننے والا ہے — یعنی جن و انس کا ٹھکانہ — جہنم ہے — سوائے جو اللہ چاہے۔
۵۔ عملی سبق: جنوں کی — دوستی — سے بچو؛ اللہ کی اطاعت کرو۔"""
),
918: (
"اور اسی طرح — ہم — ظالموں میں سے ایک — کو — دوسرے — پر — ان کی کمائی کے مطابق — مسلط کرتے ہیں",
"""۱۔ ظالم — ایک دوسرے پر مسلط — ہو سکتے ہیں۔
۲۔ ’’وَكَذَٰلِكَ نُوَلِّي بَعْضَ الظَّالِمِينَ بَعْضًا بِمَا كَانُوا يَكْسِبُونَ‘‘ — اور اسی طرح — ہم — ظالموں میں سے ایک — کو — دوسرے — پر — ان کی کمائی کے مطابق — مسلط کرتے ہیں — یعنی ظالم — ایک دوسرے کا راستہ — چلتے ہیں — یہی — ان — کی سزا ہے۔
۳۔ عملی سبق: ظلم — سے بچو؛ اچھا — معاشرہ — انصاف سے — بنتا ہے۔"""
),
919: (
"اے جن و انس کی جماعت — کیا — تمہارے پاس — تم میں سے — رسول — نہیں آئے — جو تمہارے سامنے میری آیات — پڑھتے — اور تمہیں — تمہارے — اس — دن — کی ملاقات — سے ڈرا — تے — وہ کہیں گے — ہم نے اپنے نفسوں — پر گواہی دی — اور دنیاوی زندگی نے انہیں دھوکہ دیا — اور انہوں نے — اپنے نفسوں — پر — گواہی دی — کہ وہ کافر تھے",
"""۱۔ جن اور انس — دونوں کو — رسول بھیجے گئے۔
۲۔ ’’يَا مَعْشَرَ الْجِنِّ وَالْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ آيَاتِي وَيُنذِرُونَكُمْ لِقَاءَ يَوْمِكُمْ هَٰذَا‘‘ — اے جن و انس کی جماعت — کیا — تمہارے پاس — تم میں سے — رسول — نہیں آئے — جو تمہارے سامنے میری آیات — پڑھتے — اور تمہیں — تمہارے — اس — دن — کی ملاقات — سے ڈرا — تے — یعنی اللہ نے — دونوں — کو — بتایا — ڈرایا۔
۳۔ ’’قَالُوا شَهِدْنَا عَلَىٰ أَنفُسِنَا وَغَرَّتْهُمُ الْحَيَاةُ الدُّنْيَا وَشَهِدُوا عَلَىٰ أَنفُسِهِمْ أَنَّهُمْ كَانُوا كَافِرِينَ‘‘ — وہ کہیں گے — ہم نے اپنے نفسوں — پر گواہی دی — اور دنیاوی زندگی نے انہیں دھوکہ دیا — اور انہوں نے — اپنے نفسوں — پر — گواہی دی — کہ وہ کافر تھے — یعنی قیامت کے دن — سب — اپنے — گناہوں کی — گواہی — دیں گے۔
۴۔ عملی سبق: رسولوں — کی محبت — رکھو؛ اللہ کی آیات — پر ایمان لاؤ؛ دنیا کی دھوکہ بازی سے بچو۔"""
),
920: (
"یہ اس لیے کہ — تیرا رب — بستیوں — کو — ظلم — کے ساتھ — ہلاک — نہیں کرتا — جب کہ ان کے لوگ — غافل ہوں",
"""۱۔ اللہ — بغیر وجہ — بستیوں کو تباہ نہیں کرتا۔
۲۔ ’’ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ الْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَافِلُونَ‘‘ — یہ اس لیے کہ — تیرا رب — بستیوں — کو — ظلم — کے ساتھ — ہلاک — نہیں کرتا — جب کہ ان کے لوگ — غافل ہوں — یعنی اللہ — پہلے — حجت پوری کرتا ہے — پھر عذاب دیتا ہے۔
۳۔ عملی سبق: اللہ کے عذاب سے ڈرو؛ غفلت مت کرو؛ حق — کو پہچانو۔"""
),
921: (
"اور ہر ایک کے لیے — ان کے اعمال کے مطابق — درجات ہیں — اور تمہارا رب — ان — کے — اعمال سے — غافل نہیں ہے",
"""۱۔ ہر ایک کے لیے — اعمال کے مطابق — درجات۔
۲۔ ’’وَلِكُلٍّ دَرَجَاتٌ مِّمَّا عَمِلُوا وَمَا رَبُّكَ بِغَافِلٍ عَمَّا يَعْمَلُونَ‘‘ — اور ہر ایک کے لیے — ان کے اعمال کے مطابق — درجات ہیں — اور تمہارا رب — ان — کے — اعمال سے — غافل نہیں ہے — یعنی اعمال کے مطابق — درجات — ملتے ہیں — اللہ سب کچھ جانتا ہے۔
۳۔ عملی سبق: نیک اعمال کرو؛ درجات — کے — بلند ہونے کی امید رکھو۔"""
),
922: (
"اور تمہارا رب — بے نیاز — رحمت والا ہے — اگر وہ چاہے — تو تمہیں ہٹا دے — اور — تمہارے — بعد — جسے چاہے — بدل — لائے — جس طرح اس نے تمہیں — دوسری قوم کی اولاد سے بنایا",
"""۱۔ اللہ — بے نیاز — رحمت والا — ہے۔
۲۔ ’’وَرَبُّكَ الْغَنِيُّ ذُو الرَّحْمَۃِ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِن بَعْدِكُم مَّا يَشَاءُ‘‘ — اور تمہارا رب — بے نیاز — رحمت والا ہے — اگر وہ چاہے — تو تمہیں ہٹا دے — اور — تمہارے — بعد — جسے چاہے — بدل — لائے — یعنی اللہ — کسی — کا محتاج نہیں — وہ — جسے چاہے — اٹھا کر — نیا — قوم لائے۔
۳۔ ’’كَمَا أَنشَأَكُم مِّن ذُرِّيَّۃِ قَوْمٍ آخَرِينَ‘‘ — جس طرح اس نے تمہیں — دوسری قوم کی اولاد سے بنایا — یعنی پچھلی امتیں — ختم — ہوئیں — نئی آئیں — یہ اللہ کا خود — کا — نظام ہے۔
۴۔ عملی سبق: اللہ کی بے نیازی — کو جانو؛ اللہ کا شکر ادا کرو؛ نبی کی امت — کی قدر کرو۔"""
),
}
